import { Injectable, Logger } from '@nestjs/common';
import { EventPattern, Payload } from '@nestjs/microservices';

interface ClickEvent {
  clickId: string;
  adId: string;
  timestamp: number;
}

@Injectable()
export class ClickAggregatorConsumer {
  private readonly logger = new Logger(ClickAggregatorConsumer.name);

  // Tracks every clickId we've ever processed, so a Kafka retry/redelivery
  // of the same message doesn't get folded into the window counts twice.
  private readonly seenClickIds = new Set<string>();

  // In-memory tumbling-window aggregate, later batch-flushed to ClickHouse
  // by a separate scheduled job (not shown).
  private readonly windowCounts = new WindowAggregate();

  @EventPattern('ad.clicks')
  handleClick(@Payload() message: Record<string, unknown>): void {
    const event = this.parseEvent(message);
    const windowStart = this.deriveWindowStart(event.timestamp);

    if (this.seenClickIds.has(event.clickId)) {
      // already counted, skip
      return;
    }

    this.seenClickIds.add(event.clickId);
    this.windowCounts.increment(event.adId, windowStart);
  }

  private parseEvent(message: Record<string, unknown>): ClickEvent {
    return {
      clickId: String(message.clickId),
      adId: String(message.adId),
      timestamp: Number(message.timestamp),
    };
  }

  private deriveWindowStart(timestamp: number): number {
    const ONE_MINUTE_MS = 60_000;
    return Math.floor(timestamp / ONE_MINUTE_MS) * ONE_MINUTE_MS;
  }
}

/**
 * Per-minute tumbling-window counter, keyed by adId + windowStart.
 * Lives only in process heap until the next flush cycle.
 */
class WindowAggregate {
  private readonly counts = new Map<string, number>();

  increment(adId: string, windowStart: number): void {
    const key = `${adId}:${windowStart}`;
    this.counts.set(key, (this.counts.get(key) ?? 0) + 1);
  }

  snapshot(): ReadonlyMap<string, number> {
    return new Map(this.counts);
  }
}
